B.aJT=A.a(s(["Radiografia de t\xf3rax \u2014 PA e perfil: consolida\xe7\xe3o, derrame, multilobar, padr\xe3o intersticial","TC de t\xf3rax \u2014 superior \xe0 RX; indicada em casos at\xedpicos, imunocomprometidos, sem resposta em 72h","Gasometria arterial \u2014 PaO2/FiO2; A-a gradient; indica\xe7\xe3o de HFNI, VNI ou VM","Hemograma + PCR + procalcitonina \u2014 PCT <0,1 \xb5g/L favorece viral \u2192 discutir ATB","Hemocultura \xd7 2 amostras \u2014 antes do ATB em PAC grave; positividade 10\u201315%","Ant\xedgeno urin\xe1rio Legionella + Pneumococo \u2014 r\xe1pido, espec\xedfico, n\xe3o sofre interfer\xeancia do ATB","Painel viral respirat\xf3rio (PCR) \u2014 influenza A/B, COVID-19, RSV, parainfluenza","Lavado broncoalveolar (BAL) \u2014 imunocomprometido: PCP, CMV, Aspergillus","BNP/NT-proBNP \u2014 diferenciar EAP cardiog\xeanico de PAC bilateral","Lactato s\xe9rico \u2014 sepse associada: meta <2 mmol/L ap\xf3s ressuscita\xe7\xe3o"]),t.s)
B.beQ=A.a(s(["Radiograf\xeda de t\xf3rax \u2014 consolidaci\xf3n, derrame, multilobar, patr\xf3n intersticial","TC de t\xf3rax \u2014 superior a RX; indicada en casos at\xedpicos","Gasometr\xeda arterial \u2014 PaO2/FiO2; indicaci\xf3n de HFNI, VNI o VM","Hemograma + PCR + procalcitonina \u2014 PCT <0,1 \xb5g/L favorece viral","Hemocultivo \xd7 2 muestras \u2014 antes del ATB en NAC grave","Ant\xedgeno urinario Legionella + Neumococo \u2014 r\xe1pido, espec\xedfico","Panel viral respiratorio (PCR) \u2014 influenza A/B, COVID-19","Lactato s\xe9rico \u2014 sepsis asociada"]),t.s)
