B.aZX=A.a(s(["Pantoprazol/Omeprazol \u2014 80 mg IV bolus + 8 mg/h infus\xe3o cont\xednua \xd7 72h (reduz Forrest Ia para IIa); manuten\xe7\xe3o VO ap\xf3s EDA","Concentrado de hem\xe1cias \u2014 meta Hb 7\u20138 g/dL (restritiva); n\xe3o transfundir desnecessariamente","IBP oral \u2014 ap\xf3s alta: omeprazol 40 mg/dia ou pantoprazol 40 mg/dia \xd7 4\u20138 semanas (cicatriza\xe7\xe3o ulcerosa)"]),t.s)
B.bfK=A.a(s(["Pantoprazol/Omeprazol \u2014 80 mg IV bolo + 8 mg/h \xd7 72 h; mantenimiento VO tras EDA","Concentrado de eritrocitos \u2014 meta Hb 7\u20138 g/dL (restrictiva)"]),t.s)
B.bBn=new A.b(B.c,[B.aZX,B.bfK],t.M)
