B.aYk=A.a(s(["SUPURATIVAS: abscesso periamigdaliano (mais comum), abscesso retrofar\xedngeo, otite m\xe9dia, sinusite, mastoidite","N\xc3O SUPURATIVAS: febre reum\xe1tica aguda (2\u20135 semanas \u2014 cardite em 40%), glomerulonefrite p\xf3s-estreptoc\xf3cica (1\u20133 semanas)","S\xcdNDROME DE LEMIERRE: tromboflebite s\xe9ptica jugular interna \u2192 \xeambolos s\xe9pticos pulmonares \u2014 Fusobacterium necrophorum","ESCARLATINA: exantema eritematoso + l\xedngua em framboesa \u2192 complica\xe7\xe3o sist\xeamica do SBHGA","FASCI\xcdTE NECROTIZANTE: rara mas grave \u2014 extens\xe3o para tecidos cervicais profundos"]),t.s)
B.aYB=A.a(s(["SUPURATIVAS: absceso periamigdalino (m\xe1s com\xfan), absceso retrofar\xedngeo, otitis media, sinusitis","NO SUPURATIVAS: fiebre reum\xe1tica aguda (2\u20135 semanas \u2014 carditis en 40%), glomerulonefritis (1\u20133 semanas)","S\xcdNDROME DE LEMIERRE: tromboflebitis s\xe9ptica yugular \u2192 \xe9mbolos s\xe9pticos pulmonares","ESCARLATINA: exantema eritematoso + lengua en frambuesa","FASCITIS NECROTIZANTE: rara pero grave"]),t.s)
B.bBV=new A.b(B.c,[B.aYk,B.aYB],t.M)
