B.cm5=new A.e(["gemfibrozil","pravastatina",B.o,"Inhibici\xf3n de la glicuronida\xe7\xe3o da estatina pelo gemfibrozil, aumentando dr\xe1sticamente os niveles plasm\xe1ticos","Riesgo alt\xedssimo de miopat\xeda grave e rabdomi\xf3lisis fatal","Evitar la combinaci\xf3n. Se fibrato for essencial, o fenofibrato \xe9 prefer\xedvel e mais seguro com estatinas","ALTO RIESGO DE RABDOMI\xd3LISIS \u2014 Contraindicado",B.i,B.d4,B.a4])
B.c8P=new A.e(["gemfibrozil","repaglinida",B.E,"Inhibici\xf3n potente do CYP2C8 e OATP1B1 pelo gemfibrozil","Aumento de at\xe9 8 vezes na concentraci\xf3n de repaglinida, causando hipoglucemia severa e prolongada","Combinaci\xf3n contraindicada.","HIPOGLUCEMIA GRAVE \u2014 Contraindicado",B.i,B.a3i,B.dZ])
B.chI=new A.e(["colestiramina","warfarina",B.u,"Liga\xe7\xe3o da resina \xe0 varfarina no l\xfamen intestinal","Reducci\xf3n de la absorci\xf3n da varfarina, diminuindo o INR e elevando o riesgo tromb\xf3tico","Administrar varfarina pelo menos 1 hora antes ou 4 a 6 horas despu\xe9s de a colestiramina","MONITORAR INR \u2014 Riesgo de fracaso terap\xe9utica",B.i,B.a3c,B.x])
B.ccM=new A.e(["colestiramina","levotiroxina",B.o,"Sequestro da levotiroxina no trato gastrointestinal formando complexo insoluble","Falha no tratamiento do hipotiroidismo (elevaci\xf3n do TSH)","Separar a administra\xe7\xe3o por pelo menos 4 a 6 horas","FALHA DE ABSOR\xc7\xc3O \u2014 Espa\xe7ar dosiss rigurosamente",B.i,B.a9,B.a_])
B.vA=A.a(s(["FDA Drug Label","Micromedex 2024","UpToDate 2024"]),t.s)
B.c3R=new A.e(["sofosbuvir","amiodarona",B.E,"Mecanismo desconhecido, possivelmente disfun\xe7\xe3o acentuada do n\xf3 sinusal mioc\xe1rdico","Bradicardia sintom\xe1tica grave, bloqueio card\xedaco fatal ou necessidade marcapasso","Combinaci\xf3n totalmente contraindicada. Si inevitable, monitoramento card\xedaco cont\xednuo hospitalar por 48h","BRADICARDIA FATAL \u2014 Contraindicado",B.i,B.k5,B.vA])
B.c3U=new A.e(["ledipasvir","omeprazol",B.o,"O ledipasvir necessita de ambiente \xe1cido no est\xf4mago para ser absorvido. Os IBP anulam essa acidez","Fracaso virol\xf3gico no tratamiento da Hepatite C por subdosagem de ledipasvir","Evitar IBP. Se necesario, administrar simult\xe1neamente com est\xf4mago vazio usando dosis m\xe1x de omeprazol 20mg","FRACASO TERAP\xc9UTICO \u2014 Absorci\xf3n comprometida",B.i,B.aQ,B.c0])
B.c8O=new A.e(["velpatasvir","carbamazepina",B.o,"Inducci\xf3n potente da P-glicoprote\xedna (P-gp) e CYP450 pela carbamazepina","Reducci\xf3n dr\xe1stica nos niveles de velpatasvir, levando \xe0 perda de efic\xe1cia antiviral","Evitar o uso concomitante de inductores fortes durante o tratamiento da Hepatite C","PERDA DE EFIC\xc1CIA ANTIVIRAL \u2014 Evitar combinaci\xf3n",B.i,B.hn,B.dA])
B.cjb=new A.e(["clozapina","carbamazepina",B.E,"Efecto aditivo/sin\xe9rgico na toxicidad da medula \xf3ssea","Aumento dram\xe1tico no riesgo de agranulocitose e aplasia medular fatal","Combinaci\xf3n absolutamente contraindicada. Escolher outro estabilizador do humor (ex: Valproato)","AGRANULOCITOSE FATAL \u2014 Contraindicado",B.i,B.l4,B.a4])
B.cnd=new A.e(["ziprasidona","amiodarona",B.E,"Sinergismo na inhibici\xf3n dos canais de pot\xe1ssio retificadores mioc\xe1rdicos (hERG)","Prolonga\xe7\xe3o extrema do intervalo QT e riesgo de Torsades de Pointes","Contraindicado o uso conjunto com outros f\xe1rmacos que prolongam o QT de forma conhecida","RIESGO DE TORSADES DE POINTES \u2014 Contraindicado",B.i,B.b2,B.a_])
B.c7R=new A.e(["cariprazina","cetoconazol",B.u,"Inhibici\xf3n potente del CYP3A4 pelo cetoconazol","Aumento significativo das concentraciones de cariprazina e seus metab\xf3litos ativos (DDCAR)","Reducir la dosis de cariprazina \xe0 metade e monitorar acatisia e parkinsonismo","RISCO EXTRAPIRAMIDAL \u2014 Reducir dosis",B.z,B.fC,B.dZ])
B.cbp=new A.e(["lurasidona","diltiazem",B.o,"Inhibici\xf3n moderada a forte do CYP3A4 pelo diltiazem","Elevaci\xf3n aguda da lurasidona, aumentando sedaci\xf3n, acatisia e hipotensi\xf3n","A dosis de lurasidona n\xe3o deve exceder 40 mg/dia quando coadministrada com diltiazem","AJUSTE DE DOSIS NECESS\xc1RIO \u2014 Riesgo de toxicidad",B.i,B.fC,B.a_])
B.cmv=new A.e(["donepezila","butilescopolamina",B.o,"Antagonismo farmacodin\xe2mico direto (Colin\xe9rgico vs Anticolin\xe9rgico)","Anula\xe7\xe3o da efic\xe1cia do tratamiento para Alzheimer (piora cognitiva) e exacerba\xe7\xe3o anticolin\xe9rgica perif\xe9rica","Evitar o uso de anticolin\xe9rgicos sist\xeamicos en pacientes com dem\xeancia tratada farmacologicamente","ANTAGONISMO TERAP\xcaUTICO \u2014 Piora do Alzheimer",B.i,B.wG,B.x])
